export const scripts: string[] = ["\n    function updateEstimatedPremium() {\n      const model = document.getElementById('carModel').value;\n      const ncb = parseInt(document.getElementById('ncbValue').value, 10);\n      const year = parseInt(document.getElementById('regYear').value, 10);\n      \n      let baseGross = 14500;\n      if (model === 'swift') baseGross = 9500;\n      if (model === 'creta') baseGross = 15800;\n      if (model === 'nexon') baseGross = 13200;\n      if (model === 'city') baseGross = 14900;\n      if (model === 'innova') baseGross = 24500;\n      if (model === 'other') baseGross = 11800;\n\n      // Adjust for age\n      if (year === 2024) baseGross *= 1.25;\n      if (year === 2023) baseGross *= 1.1;\n      if (year === 2021) baseGross *= 0.9;\n      if (year <= 2020) baseGross *= 0.8;\n\n      const strikePrice = Math.round(baseGross);\n      const discountPercentage = (ncb / 100) * 0.75; // OD discount factor\n      const finalPrice = Math.round(baseGross * (1 - discountPercentage));\n      const saved = strikePrice - finalPrice;\n\n      document.getElementById('strikePrice').textContent = '\u20b9' + strikePrice.toLocaleString('en-IN');\n      document.getElementById('finalPrice').textContent = '\u20b9' + finalPrice.toLocaleString('en-IN');\n      document.getElementById('savedAmountBadge').textContent = 'Save \u20b9' + saved.toLocaleString('en-IN');\n    }\n\n    function calculateQuote() {\n      const reg = document.getElementById('regNumber').value.trim();\n      const modelText = document.getElementById('carModel').options[document.getElementById('carModel').selectedIndex].text;\n      const ncb = document.getElementById('ncbValue').value;\n      const estPrice = document.getElementById('finalPrice').textContent;\n\n      const message = encodeURIComponent(`Hello Deeksha Insurance and Financial Services Nanganallur, I calculated an ICICI Lombard Car Insurance estimate for my vehicle (${reg}, ${modelText}, ${ncb}% NCB). Indicative quote: ${estPrice}. Please share the official ICICI Lombard policy quotation link.`);\n      window.open(`https://wa.me/916374423164?text=${message}`, '_blank');\n    }\n\n    function toggleFaq(button) {\n      const card = button.parentElement;\n      const body = card.querySelector('.faq-body');\n      const icon = button.querySelector('.faq-icon');\n\n      const isHidden = body.classList.contains('hidden');\n\n      // Close all other FAQs\n      document.querySelectorAll('.faq-body').forEach(el => el.classList.add('hidden'));\n      document.querySelectorAll('.faq-icon').forEach(el => el.classList.remove('rotate-180'));\n\n      if (isHidden) {\n        body.classList.remove('hidden');\n        icon.classList.add('rotate-180');\n      }\n    }\n\n    // Initialize default calculator values on page render\n    document.addEventListener('DOMContentLoaded', () => {\n      updateEstimatedPremium();\n    });\n  "];
